-- T-PLAT-02 / KITA-PLAT-02: Kita core schema, PostgreSQL 18 dialect.
-- Translated from the reviewed planning DDL (docs/kita-plan/sql/001_core.sql) for an ISOLATED fresh install.
-- Apply once to an EMPTY database as a migration owner with CREATEROLE. Schema/DDL only:
-- this migration carries NO data import of sandbox balances or any money rows.
-- The only INSERTs below are non-monetary reference/config rows (currencies codes+exponents,
-- attempt_edges state-machine rules); see invariant.ts "no money rows imported" enforcement.
--
-- Expand-safe ordering (RB-PLATFORM): every object is created before it is referenced;
-- the whole file runs in ONE transaction so a partial apply rolls back completely.
BEGIN;

CREATE SCHEMA kita;
SET search_path = kita, pg_catalog;

-- Least-privilege service roles (NOLOGIN groups; runtime principals are granted membership out-of-band).
DO $$ BEGIN
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='kita_api') THEN CREATE ROLE kita_api NOLOGIN; END IF;
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='kita_worker') THEN CREATE ROLE kita_worker NOLOGIN; END IF;
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='kita_posting') THEN CREATE ROLE kita_posting NOLOGIN; END IF;
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='kita_auditor') THEN CREATE ROLE kita_auditor NOLOGIN; END IF;
END $$;

-- Reference data: currency codes and exponents ONLY. No balances, no amounts.
CREATE TABLE currencies(code text PRIMARY KEY CHECK(code ~ '^[A-Z]{3}$'), exponent smallint NOT NULL CHECK(exponent BETWEEN 0 AND 6));
INSERT INTO currencies VALUES ('USD',2),('PHP',2),('CAD',2),('GBP',2),('EUR',2),('JPY',0),('SGD',2),('AUD',2);

CREATE TABLE books(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legal_entity text NOT NULL UNIQUE, functional_currency text NOT NULL REFERENCES currencies, status text NOT NULL DEFAULT 'disabled' CHECK(status IN ('disabled','sandbox','live','closed')));
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, subject text NOT NULL, country text NOT NULL CHECK(country ~ '^[A-Z]{2}$'), region text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','restricted','closed')), profile_cipher bytea, key_ref text, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(book_id,subject), UNIQUE(id,book_id));
CREATE TABLE policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, kind text NOT NULL, version bigint NOT NULL CHECK(version>0), body jsonb NOT NULL CHECK(jsonb_typeof(body)='object'), effective_at timestamptz NOT NULL, expires_at timestamptz, approval_id uuid, UNIQUE(book_id,kind,version), CHECK(expires_at IS NULL OR expires_at>effective_at));
CREATE TABLE capabilities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, origin_country text NOT NULL, origin_region text NOT NULL DEFAULT '*', destination_country text NOT NULL, source_currency text NOT NULL REFERENCES currencies, destination_currency text NOT NULL REFERENCES currencies, product text NOT NULL, funding_method text NOT NULL, payout_method text NOT NULL, enabled boolean NOT NULL DEFAULT false, policy_id uuid NOT NULL REFERENCES policies, UNIQUE(book_id,origin_country,origin_region,destination_country,source_currency,destination_currency,product,funding_method,payout_method));
CREATE TABLE provider_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, provider text NOT NULL, external_account text NOT NULL, environment text NOT NULL CHECK(environment IN ('sandbox','production')), currency text NOT NULL REFERENCES currencies, enabled boolean NOT NULL DEFAULT false, capability jsonb NOT NULL DEFAULT '{}', UNIQUE(provider,external_account,environment,currency), UNIQUE(id,book_id));
CREATE TABLE evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, provider_account_id uuid, source text NOT NULL, external_event_id text NOT NULL, body_hash text NOT NULL CHECK(body_hash ~ '^[a-f0-9]{64}$'), object_ref text NOT NULL, verified boolean NOT NULL DEFAULT false, occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE NULLS NOT DISTINCT(book_id,provider_account_id,source,external_event_id), UNIQUE(id,book_id), FOREIGN KEY(provider_account_id,book_id) REFERENCES provider_accounts(id,book_id));
CREATE TABLE recipients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL, customer_id uuid NOT NULL, active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1, UNIQUE(id,book_id,customer_id), FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id));
CREATE TABLE recipient_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid NOT NULL, book_id uuid NOT NULL, customer_id uuid NOT NULL, version bigint NOT NULL CHECK(version>0), method text NOT NULL CHECK(method IN ('bank','gcash','maya','cash_pickup','bill')), destination_cipher bytea NOT NULL, key_ref text NOT NULL, destination_hmac text NOT NULL, destination_mask text NOT NULL, validated_evidence_id uuid REFERENCES evidence, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(recipient_id,version), UNIQUE(id,book_id,customer_id), FOREIGN KEY(recipient_id,book_id,customer_id) REFERENCES recipients(id,book_id,customer_id));
CREATE TABLE quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL, customer_id uuid NOT NULL, recipient_version_id uuid NOT NULL, source_currency text NOT NULL REFERENCES currencies, destination_currency text NOT NULL REFERENCES currencies, principal_minor bigint NOT NULL CHECK(principal_minor>0), fee_minor bigint NOT NULL CHECK(fee_minor>=0), discount_minor bigint NOT NULL DEFAULT 0 CHECK(discount_minor>=0), tax_minor bigint NOT NULL DEFAULT 0 CHECK(tax_minor>=0), total_minor bigint NOT NULL CHECK(total_minor>0), receive_minor bigint NOT NULL CHECK(receive_minor>0), rate_numerator numeric(38,0) NOT NULL CHECK(rate_numerator>0), rate_denominator numeric(38,0) NOT NULL CHECK(rate_denominator>0), pricing_policy_id uuid NOT NULL REFERENCES policies, route_id uuid NOT NULL REFERENCES provider_accounts, provider_quote_ref text NOT NULL, disclosure_hash text NOT NULL, terms jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, funding_deadline timestamptz NOT NULL, UNIQUE(id,book_id,customer_id,recipient_version_id), CHECK(discount_minor<=fee_minor), CHECK(total_minor::numeric=principal_minor::numeric+fee_minor-discount_minor+tax_minor), CHECK(expires_at>created_at AND funding_deadline>expires_at), FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id), FOREIGN KEY(recipient_version_id,book_id,customer_id) REFERENCES recipient_versions(id,book_id,customer_id));
CREATE TABLE transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL, customer_id uuid NOT NULL, quote_id uuid NOT NULL UNIQUE, recipient_version_id uuid NOT NULL, reference text NOT NULL UNIQUE, accepted_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 1 CHECK(version>0), compliance_state text NOT NULL DEFAULT 'pending' CHECK(compliance_state IN ('pending','review','cleared','blocked')), lifecycle text NOT NULL DEFAULT 'active' CHECK(lifecycle IN ('active','cancelled','closed')), payment_authorized_at timestamptz, delivered_at timestamptz, UNIQUE(id,book_id), UNIQUE(id,book_id,customer_id), FOREIGN KEY(quote_id,book_id,customer_id,recipient_version_id) REFERENCES quotes(id,book_id,customer_id,recipient_version_id));
-- Non-remittance monetary aggregates prevent fake transfers for wallet topups/withdrawals.
CREATE TABLE money_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, customer_id uuid NOT NULL, transfer_id uuid UNIQUE, kind text NOT NULL CHECK(kind IN ('remittance','topup','withdrawal','wallet_conversion','wallet_transfer','bill','treasury')), source_currency text NOT NULL REFERENCES currencies, source_minor bigint NOT NULL CHECK(source_minor>0), destination_currency text REFERENCES currencies, destination_minor bigint CHECK(destination_minor>0), policy_id uuid NOT NULL REFERENCES policies, consent_hash text NOT NULL, state text NOT NULL DEFAULT 'accepted' CHECK(state IN ('accepted','processing','unknown','completed','cancelled','failed')), version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,book_id), FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id), FOREIGN KEY(transfer_id,book_id,customer_id) REFERENCES transfers(id,book_id,customer_id));
CREATE TABLE funding_instruments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL, customer_id uuid NOT NULL, provider_account_id uuid NOT NULL, method text NOT NULL CHECK(method IN ('ach','debit','credit','apple_pay','google_pay')), provider_token_cipher bytea NOT NULL, key_ref text NOT NULL, mask text NOT NULL, ownership_evidence_id uuid, state text NOT NULL CHECK(state IN ('pending','verified','restricted','revoked')), UNIQUE(id,book_id,customer_id), FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id), FOREIGN KEY(provider_account_id,book_id) REFERENCES provider_accounts(id,book_id), FOREIGN KEY(ownership_evidence_id,book_id) REFERENCES evidence(id,book_id));
CREATE TABLE mandates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), instrument_id uuid NOT NULL REFERENCES funding_instruments, terms_hash text NOT NULL, terms_version text NOT NULL, accepted_at timestamptz NOT NULL, authorization_ref text NOT NULL, maximum_minor bigint CHECK(maximum_minor>0), expires_at timestamptz);
CREATE TABLE mandate_revocations(mandate_id uuid PRIMARY KEY REFERENCES mandates, revoked_at timestamptz NOT NULL, evidence_id uuid NOT NULL REFERENCES evidence);
CREATE TABLE auth_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES customers, staff_subject text, session_hash text NOT NULL UNIQUE, audience text NOT NULL CHECK(audience IN ('kita-customer','kita-admin')), device_ref text NOT NULL, assurance text NOT NULL, expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, CHECK((customer_id IS NOT NULL)::integer+(staff_subject IS NOT NULL)::integer=1));
CREATE TABLE contact_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES customers, destination_hmac text NOT NULL, challenge_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 10), verified_at timestamptz);
CREATE TABLE rate_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_account_id uuid NOT NULL REFERENCES provider_accounts, source_currency text NOT NULL REFERENCES currencies, destination_currency text NOT NULL REFERENCES currencies, rate_numerator numeric(38,0) NOT NULL CHECK(rate_numerator>0), rate_denominator numeric(38,0) NOT NULL CHECK(rate_denominator>0), as_of timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), evidence_id uuid NOT NULL REFERENCES evidence);
CREATE TABLE wallet_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL, customer_id uuid NOT NULL, source_currency text NOT NULL REFERENCES currencies, destination_currency text NOT NULL REFERENCES currencies, source_minor bigint NOT NULL CHECK(source_minor>0), receive_minor bigint NOT NULL CHECK(receive_minor>0), fee_minor bigint NOT NULL CHECK(fee_minor>=0), rate_snapshot_id uuid NOT NULL REFERENCES rate_snapshots, provider_quote_ref text NOT NULL, policy_id uuid NOT NULL REFERENCES policies, disclosure_hash text NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id));
CREATE TABLE limit_buckets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, subject_ref text NOT NULL, policy_id uuid NOT NULL REFERENCES policies, currency text NOT NULL REFERENCES currencies, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, maximum_minor bigint NOT NULL CHECK(maximum_minor>=0), reserved_minor bigint NOT NULL DEFAULT 0 CHECK(reserved_minor>=0), consumed_minor bigint NOT NULL DEFAULT 0 CHECK(consumed_minor>=0), UNIQUE(book_id,subject_ref,policy_id,currency,window_start), CHECK(window_end>window_start), CHECK(reserved_minor::numeric+consumed_minor<=maximum_minor));
CREATE TABLE limit_reservations(operation_id uuid NOT NULL REFERENCES money_operations, bucket_id uuid NOT NULL REFERENCES limit_buckets, amount_minor bigint NOT NULL CHECK(amount_minor>0), state text NOT NULL CHECK(state IN ('reserved','consumed','released')), PRIMARY KEY(operation_id,bucket_id));
CREATE TABLE accounting_periods(book_id uuid NOT NULL REFERENCES books, start_date date NOT NULL, end_date date NOT NULL, state text NOT NULL CHECK(state IN ('open','closed')), closed_at timestamptz, approval_ref text, PRIMARY KEY(book_id,start_date), CHECK(end_date>start_date));
CREATE TABLE consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL, customer_id uuid NOT NULL, transfer_id uuid, kind text NOT NULL, document_version text NOT NULL, document_hash text NOT NULL, locale text NOT NULL, accepted_at timestamptz NOT NULL, session_ref text NOT NULL, FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id), FOREIGN KEY(transfer_id,book_id,customer_id) REFERENCES transfers(id,book_id,customer_id));
CREATE TABLE drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL, customer_id uuid NOT NULL, version bigint NOT NULL DEFAULT 1, data jsonb NOT NULL DEFAULT '{}', expires_at timestamptz NOT NULL, FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id));
CREATE TABLE holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transfer_id uuid NOT NULL REFERENCES transfers, scope text NOT NULL CHECK(scope IN ('all','funding','fx','payout','refund','withdrawal')), reason_code text NOT NULL, owner_ref text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolution_evidence uuid REFERENCES evidence);
CREATE INDEX holds_active ON holds(transfer_id,scope) WHERE resolved_at IS NULL;
CREATE TABLE command_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, actor_id text NOT NULL, operation text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), request_hash text NOT NULL, state text NOT NULL CHECK(state IN ('running','succeeded','rejected','unknown')), resource_id uuid, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(book_id,actor_id,operation,key));
CREATE TABLE provider_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL, transfer_id uuid, operation_id uuid NOT NULL, provider_account_id uuid NOT NULL, leg text NOT NULL CHECK(leg IN ('funding','fx','payout','refund')), sequence integer NOT NULL CHECK(sequence>0), external_reference text NOT NULL, provider_reference text, request_hash text NOT NULL, request_ref text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL REFERENCES currencies, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','submitting','pending','authorized','captured','settled','accepted','unknown','paid','rejected','cancelled','returned','partially_returned')), generation bigint NOT NULL DEFAULT 0, lease_until timestamptz, version bigint NOT NULL DEFAULT 1, last_evidence_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(operation_id,leg,sequence), UNIQUE(provider_account_id,external_reference), UNIQUE(provider_account_id,provider_reference), FOREIGN KEY(transfer_id,book_id) REFERENCES transfers(id,book_id), FOREIGN KEY(operation_id,book_id) REFERENCES money_operations(id,book_id), FOREIGN KEY(provider_account_id,book_id) REFERENCES provider_accounts(id,book_id), FOREIGN KEY(last_evidence_id,book_id) REFERENCES evidence(id,book_id));
-- Ordered locks: exactly one live payout authority per operation; writers take the operation lock first.
CREATE UNIQUE INDEX one_payout_authority ON provider_attempts(operation_id) WHERE leg='payout' AND state NOT IN ('rejected','cancelled','returned');
CREATE TABLE attempt_edges(leg text NOT NULL, from_state text NOT NULL, to_state text NOT NULL, evidence_required boolean NOT NULL, PRIMARY KEY(leg,from_state,to_state));
-- Config rows: transition RULES only (state machine edges). No amounts, no balances, no outcomes.
INSERT INTO attempt_edges
SELECT l, f, t, e FROM (VALUES
('funding','queued','submitting',false),('funding','submitting','pending',true),('funding','submitting','unknown',false),('funding','pending','authorized',true),('funding','authorized','captured',true),('funding','pending','settled',true),('funding','captured','settled',true),('funding','settled','returned',true),('funding','captured','returned',true),
('fx','queued','submitting',false),('fx','submitting','accepted',true),('fx','accepted','settled',true),('fx','submitting','unknown',false),
('payout','queued','submitting',false),('payout','submitting','accepted',true),('payout','submitting','unknown',false),('payout','accepted','paid',true),('payout','accepted','pending',true),('payout','pending','paid',true),('payout','paid','partially_returned',true),('payout','paid','returned',true),('payout','partially_returned','returned',true),
('refund','queued','submitting',false),('refund','submitting','pending',true),('refund','submitting','unknown',false),('refund','pending','paid',true),('refund','paid','returned',true)
) AS v(l,f,t,e);
INSERT INTO attempt_edges SELECT l,s,t,true FROM unnest(ARRAY['funding','fx','payout','refund']) l CROSS JOIN unnest(ARRAY['submitting','pending','unknown','accepted','authorized']) s CROSS JOIN unnest(ARRAY['rejected','cancelled']) t ON CONFLICT DO NOTHING;
INSERT INTO attempt_edges SELECT l,'unknown',t,true FROM unnest(ARRAY['funding','fx','payout','refund']) l CROSS JOIN unnest(ARRAY['pending','accepted']) t ON CONFLICT DO NOTHING;
INSERT INTO attempt_edges VALUES ('funding','unknown','settled',true),('funding','unknown','captured',true),('funding','unknown','authorized',true),('fx','unknown','settled',true),('payout','unknown','paid',true),('refund','unknown','paid',true),('funding','queued','cancelled',false),('fx','queued','cancelled',false),('payout','queued','cancelled',false),('refund','queued','cancelled',false);
CREATE TABLE transfer_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transfer_id uuid NOT NULL REFERENCES transfers, version bigint NOT NULL, event_type text NOT NULL, source_key text NOT NULL, evidence_id uuid REFERENCES evidence, public_payload jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(transfer_id,version), UNIQUE(transfer_id,source_key));
CREATE TABLE ledger_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, code text NOT NULL, currency text NOT NULL REFERENCES currencies, account_type text NOT NULL CHECK(account_type IN ('asset','liability','equity','revenue','expense')), normal_side text NOT NULL CHECK(normal_side IN ('D','C')), customer_id uuid, enforce_nonnegative boolean NOT NULL DEFAULT false, UNIQUE(book_id,code,currency), UNIQUE(id,book_id,currency), FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id), CHECK((account_type IN ('asset','expense') AND normal_side='D') OR (account_type IN ('liability','equity','revenue') AND normal_side='C')));
-- account_balances ships EMPTY: sandbox balances are never imported; projections exist only after
-- real postings through post_journal within an open period. See invariant.ts money_columns list.
CREATE TABLE account_balances(account_id uuid PRIMARY KEY REFERENCES ledger_accounts, normal_minor numeric(38,0) NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 0);
CREATE TABLE journals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, event_key text NOT NULL, request_hash text NOT NULL, policy_id uuid NOT NULL REFERENCES policies, evidence_id uuid NOT NULL, transfer_id uuid, reversal_of uuid UNIQUE REFERENCES journals, adjustment_of uuid REFERENCES journals, description text NOT NULL, effective_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), posting_date date NOT NULL DEFAULT ((clock_timestamp() AT TIME ZONE 'UTC')::date), creation_tx bigint NOT NULL DEFAULT txid_current(), UNIQUE(book_id,event_key), UNIQUE(id,book_id), FOREIGN KEY(evidence_id,book_id) REFERENCES evidence(id,book_id), FOREIGN KEY(transfer_id,book_id) REFERENCES transfers(id,book_id));
CREATE TABLE journal_lines(journal_id uuid NOT NULL, line_no integer NOT NULL CHECK(line_no>0), book_id uuid NOT NULL, account_id uuid NOT NULL, currency text NOT NULL, side text NOT NULL CHECK(side IN ('D','C')), amount_minor bigint NOT NULL CHECK(amount_minor>0), PRIMARY KEY(journal_id,line_no), FOREIGN KEY(journal_id,book_id) REFERENCES journals(id,book_id), FOREIGN KEY(account_id,book_id,currency) REFERENCES ledger_accounts(id,book_id,currency));
CREATE INDEX journal_lines_account ON journal_lines(account_id,journal_id);
CREATE TABLE liquidity_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL REFERENCES money_operations, transfer_id uuid REFERENCES transfers, account_id uuid NOT NULL REFERENCES ledger_accounts, amount_minor bigint NOT NULL CHECK(amount_minor>0), purpose text NOT NULL, state text NOT NULL CHECK(state IN ('reserved','consumed','released')), expires_at timestamptz, UNIQUE(operation_id,account_id,purpose));
CREATE TABLE refund_obligations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL REFERENCES money_operations, transfer_id uuid REFERENCES transfers, event_key text NOT NULL UNIQUE, principal_minor bigint NOT NULL CHECK(principal_minor>=0), fee_minor bigint NOT NULL CHECK(fee_minor>=0), tax_minor bigint NOT NULL DEFAULT 0 CHECK(tax_minor>=0), goodwill_minor bigint NOT NULL DEFAULT 0 CHECK(goodwill_minor>=0), currency text NOT NULL REFERENCES currencies, due_at timestamptz NOT NULL, reason_code text NOT NULL, evidence_id uuid NOT NULL REFERENCES evidence, journal_id uuid NOT NULL REFERENCES journals, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refund_allocations(obligation_id uuid NOT NULL REFERENCES refund_obligations, attempt_id uuid NOT NULL REFERENCES provider_attempts, amount_minor bigint NOT NULL CHECK(amount_minor>0), PRIMARY KEY(obligation_id,attempt_id));
CREATE TABLE disputes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transfer_id uuid NOT NULL REFERENCES transfers, funding_attempt_id uuid NOT NULL REFERENCES provider_attempts, provider_case_ref text NOT NULL UNIQUE, state text NOT NULL CHECK(state IN ('open','evidence_due','won','lost','closed')), amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL REFERENCES currencies, due_at timestamptz, evidence_id uuid NOT NULL REFERENCES evidence);
CREATE TABLE inbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_account_id uuid NOT NULL REFERENCES provider_accounts, delivery_id text NOT NULL, payload_hash text NOT NULL, raw_object_ref text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), state text NOT NULL DEFAULT 'received' CHECK(state IN ('received','processing','applied','quarantined')), last_error text, UNIQUE(provider_account_id,delivery_id));
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL, event_type text NOT NULL, schema_version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), available_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, UNIQUE(aggregate_id,aggregate_version,event_type));
CREATE INDEX outbox_pending ON outbox(available_at) WHERE published_at IS NULL;
CREATE TABLE consumer_inbox(consumer text NOT NULL, event_id uuid NOT NULL, applied_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer,event_id));
CREATE TABLE timers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_id uuid NOT NULL, timer_kind text NOT NULL, due_at timestamptz NOT NULL, generation bigint NOT NULL, state text NOT NULL CHECK(state IN ('scheduled','claimed','fired','cancelled')), UNIQUE(aggregate_id,timer_kind,generation));
CREATE TABLE staff_people(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employment_ref text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE staff_identities(subject text PRIMARY KEY, person_id uuid NOT NULL REFERENCES staff_people);
CREATE TABLE staff_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES staff_people, book_id uuid NOT NULL REFERENCES books, permission text NOT NULL, max_minor bigint, currency text REFERENCES currencies, expires_at timestamptz NOT NULL);
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, requester_person_id uuid NOT NULL REFERENCES staff_people, target_id uuid NOT NULL, target_version bigint NOT NULL, command_kind text NOT NULL, payload jsonb NOT NULL, payload_hash text NOT NULL, reason text NOT NULL, expires_at timestamptz NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected','executed','invalidated')), version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approval_decisions(approval_id uuid NOT NULL REFERENCES approvals, approver_person_id uuid NOT NULL REFERENCES staff_people, decision text NOT NULL CHECK(decision IN ('approved','rejected')), signed_hash text NOT NULL, step_up_ref text NOT NULL, decided_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(approval_id,approver_person_id));
ALTER TABLE policies ADD CONSTRAINT policy_approval FOREIGN KEY(approval_id) REFERENCES approvals(id);
CREATE TABLE cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, customer_id uuid, transfer_id uuid, kind text NOT NULL CHECK(kind IN ('kyc','aml','fraud','support','complaint','error','refund','reconciliation','provider_rfi','recovery')), state text NOT NULL CHECK(state IN ('open','investigating','awaiting_customer','awaiting_provider','resolved','closed')), assigned_person uuid REFERENCES staff_people, due_at timestamptz NOT NULL, confidential boolean NOT NULL DEFAULT false, facts_ref text NOT NULL, version bigint NOT NULL DEFAULT 1, received_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(customer_id,book_id) REFERENCES customers(id,book_id), FOREIGN KEY(transfer_id,book_id) REFERENCES transfers(id,book_id));
CREATE TABLE identity_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers, case_id uuid NOT NULL REFERENCES cases, state text NOT NULL CHECK(state IN ('pending','approved','needs_info','rejected','expired','review')), policy_id uuid NOT NULL REFERENCES policies, evidence_id uuid NOT NULL REFERENCES evidence, valid_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE screenings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, subject_ref text NOT NULL, list_version text NOT NULL, policy_id uuid NOT NULL REFERENCES policies, decision text NOT NULL CHECK(decision IN ('clear','review','blocked')), evidence_id uuid NOT NULL REFERENCES evidence, valid_until timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, owner_ref text NOT NULL, object_ref text NOT NULL UNIQUE, sha256 text NOT NULL, classification text NOT NULL, scan_state text NOT NULL CHECK(scan_state IN ('quarantine','clean','rejected')), retention_until timestamptz NOT NULL, legal_hold boolean NOT NULL DEFAULT false);
CREATE TABLE statement_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, provider_account_id uuid REFERENCES provider_accounts, source text NOT NULL, sha256 text NOT NULL, object_ref text NOT NULL, period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, imported_at timestamptz NOT NULL DEFAULT now(), UNIQUE(book_id,source,sha256), CHECK(period_end>period_start));
CREATE TABLE statement_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), file_id uuid NOT NULL REFERENCES statement_files, line_number integer NOT NULL, external_ref text NOT NULL, movement_type text NOT NULL, currency text NOT NULL REFERENCES currencies, signed_minor bigint NOT NULL, value_date date NOT NULL, UNIQUE(file_id,line_number));
CREATE TABLE reconciliation_matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), statement_line_id uuid NOT NULL REFERENCES statement_lines, journal_id uuid NOT NULL REFERENCES journals, allocated_minor bigint NOT NULL CHECK(allocated_minor>0), rule_version text NOT NULL, UNIQUE(statement_line_id,journal_id));
CREATE TABLE reconciliation_breaks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL UNIQUE REFERENCES cases, statement_line_id uuid REFERENCES statement_lines, journal_id uuid REFERENCES journals, kind text NOT NULL CHECK(kind IN ('timing','missing_internal','missing_external','duplicate','amount','fee','fx','unknown_cash')), currency text NOT NULL REFERENCES currencies, difference_minor bigint NOT NULL, resolution_journal_id uuid REFERENCES journals, resolved_at timestamptz);
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, book_id uuid NOT NULL REFERENCES books, actor_ref text NOT NULL, action text NOT NULL, target_ref text NOT NULL, command_id uuid, approval_id uuid REFERENCES approvals, payload_hash text NOT NULL, previous_hash text, event_hash text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transfer_id uuid NOT NULL REFERENCES transfers, version integer NOT NULL, locale text NOT NULL, disclosure_hash text NOT NULL, document_id uuid NOT NULL REFERENCES documents, reason text NOT NULL, UNIQUE(transfer_id,version,locale));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers, event_id uuid NOT NULL, template_version text NOT NULL, channel text NOT NULL CHECK(channel IN ('email','sms','push','in_app')), category text NOT NULL CHECK(category IN ('service','security','marketing')), locale text NOT NULL, consent_ref text NOT NULL, state text NOT NULL CHECK(state IN ('queued','sending','sent','delivered','unknown','failed','suppressed')), UNIQUE(customer_id,event_id,template_version,channel));
CREATE TABLE rate_alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers, capability_id uuid NOT NULL REFERENCES capabilities, target_rate numeric(28,12) NOT NULL CHECK(target_rate>0), direction text NOT NULL CHECK(direction IN ('above','below')), amount_minor bigint NOT NULL CHECK(amount_minor>0), basis text NOT NULL CHECK(basis IN ('reference','customer_rate','effective_value')), state text NOT NULL CHECK(state IN ('armed','triggered','paused','expired')), cooldown_until timestamptz, expires_at timestamptz NOT NULL, version bigint NOT NULL DEFAULT 1);
CREATE TABLE campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, policy_id uuid NOT NULL REFERENCES policies, currency text NOT NULL REFERENCES currencies, budget_minor bigint NOT NULL CHECK(budget_minor>=0), reserved_minor bigint NOT NULL DEFAULT 0 CHECK(reserved_minor>=0), consumed_minor bigint NOT NULL DEFAULT 0 CHECK(consumed_minor>=0), CHECK(reserved_minor::numeric+consumed_minor<=budget_minor));
CREATE TABLE reward_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns, customer_id uuid NOT NULL REFERENCES customers, transfer_id uuid NOT NULL REFERENCES transfers, amount_minor bigint NOT NULL CHECK(amount_minor>=0), state text NOT NULL CHECK(state IN ('reserved','consumed','released')), UNIQUE(campaign_id,customer_id,transfer_id));
CREATE TABLE point_lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers, source_transfer_id uuid NOT NULL REFERENCES transfers, rule_version text NOT NULL, points bigint NOT NULL CHECK(points>0), vests_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, UNIQUE(source_transfer_id,rule_version), CHECK(expires_at>vests_at));
CREATE TABLE point_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers, lot_id uuid NOT NULL REFERENCES point_lots, event_key text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('earn','vest','reserve','redeem','release','expire','reverse','adjust')), units bigint NOT NULL CHECK(units>0), counter_account text NOT NULL, reversal_of uuid REFERENCES point_events, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE referrals(referee_id uuid PRIMARY KEY REFERENCES customers, referrer_id uuid NOT NULL REFERENCES customers, campaign_id uuid NOT NULL REFERENCES campaigns, qualification_transfer_id uuid UNIQUE REFERENCES transfers, state text NOT NULL CHECK(state IN ('pending','review','qualified','vested','reversed','rejected')), CHECK(referee_id<>referrer_id));
CREATE TABLE schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers, kind text NOT NULL CHECK(kind IN ('reminder','scheduled_transfer','auto_conversion')), authorization jsonb NOT NULL, policy_id uuid NOT NULL REFERENCES policies, state text NOT NULL CHECK(state IN ('active','paused','revoked','expired')), next_run timestamptz NOT NULL, version bigint NOT NULL DEFAULT 1);
CREATE TABLE schedule_runs(schedule_id uuid NOT NULL REFERENCES schedules, occurrence_at timestamptz NOT NULL, operation_id uuid NOT NULL UNIQUE, state text NOT NULL CHECK(state IN ('due','consent_required','executing','completed','failed','skipped')), PRIMARY KEY(schedule_id,occurrence_at));
CREATE TABLE bill_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transfer_id uuid NOT NULL UNIQUE REFERENCES transfers, biller_ref text NOT NULL, schema_version text NOT NULL, account_token text NOT NULL, period_ref text NOT NULL, state text NOT NULL CHECK(state IN ('validated','submitted','accepted','posted','unknown','rejected','reversed')), proof_document_id uuid REFERENCES documents);
CREATE TABLE treasury_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, kind text NOT NULL CHECK(kind IN ('fiat','stablecoin')), asset text NOT NULL, network text, custody_ref text, external_ref text NOT NULL UNIQUE, atomic_units numeric(38,0) NOT NULL CHECK(atomic_units>0), state text NOT NULL CHECK(state IN ('authorized','submitted','unknown','confirmed','settled','failed','reorged')), approval_id uuid NOT NULL REFERENCES approvals, evidence_id uuid REFERENCES evidence);
CREATE TABLE business_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL UNIQUE REFERENCES customers, registration_ref_cipher bytea NOT NULL, beneficial_owner_ref text NOT NULL, signatory_policy_id uuid NOT NULL REFERENCES policies, kyb_case_id uuid NOT NULL REFERENCES cases);
CREATE TABLE batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES business_profiles, file_document_id uuid NOT NULL REFERENCES documents, approval_id uuid NOT NULL REFERENCES approvals, state text NOT NULL CHECK(state IN ('validated','approved','processing','completed','partial','cancelled')));
CREATE TABLE batch_items(batch_id uuid NOT NULL REFERENCES batches, line_number integer NOT NULL, transfer_id uuid UNIQUE REFERENCES transfers, validation_error text, PRIMARY KEY(batch_id,line_number));
CREATE TABLE case_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases, actor_ref text NOT NULL, visibility text NOT NULL CHECK(visibility IN ('customer','staff','aml_only')), body_cipher bytea NOT NULL, key_ref text NOT NULL, document_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notification_id uuid NOT NULL REFERENCES notifications, provider text NOT NULL, external_ref text NOT NULL, state text NOT NULL CHECK(state IN ('submitted','delivered','unknown','failed')), evidence_id uuid REFERENCES evidence, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,external_ref));
CREATE TABLE notification_preferences(customer_id uuid PRIMARY KEY REFERENCES customers, version bigint NOT NULL DEFAULT 1, locale text NOT NULL, time_zone text NOT NULL, preferences jsonb NOT NULL, consent_id uuid NOT NULL REFERENCES consents);
CREATE TABLE fx_trades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books, provider_account_id uuid NOT NULL REFERENCES provider_accounts, external_ref text NOT NULL, source_currency text NOT NULL REFERENCES currencies, source_minor bigint NOT NULL CHECK(source_minor>0), destination_currency text NOT NULL REFERENCES currencies, destination_minor bigint NOT NULL CHECK(destination_minor>0), value_date date NOT NULL, evidence_id uuid NOT NULL REFERENCES evidence, UNIQUE(provider_account_id,external_ref));
CREATE TABLE fx_allocations(trade_id uuid NOT NULL REFERENCES fx_trades, operation_id uuid NOT NULL REFERENCES money_operations, source_minor bigint NOT NULL CHECK(source_minor>0), destination_minor bigint NOT NULL CHECK(destination_minor>0), PRIMARY KEY(trade_id,operation_id));
CREATE INDEX transfers_customer_date ON transfers(customer_id,accepted_at DESC,id);
CREATE INDEX attempts_recovery ON provider_attempts(state,updated_at) WHERE state IN ('unknown','submitting','pending','accepted');
CREATE INDEX cases_queue ON cases(book_id,kind,state,due_at);

-- Install-time money guard (INVARIANT): sandbox balances must NEVER become live cash, so direct
-- INSERTs carrying balance/amount data into ledger/money tables are rejected unless they run
-- inside post_journal (which sets a per-transaction flag). Only the two balance-bearing ledger
-- tables need it: every other money table already has zero rows at CREATE time, which the
-- migrate runner's empty-table assertion proves.
CREATE FUNCTION guard_money_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF current_setting('kita.posting_allowed', true) IS DISTINCT FROM 'on' THEN
  RAISE EXCEPTION 'T-PLAT-02 invariant: no balance/amount rows may be inserted outside post_journal (sandbox balances never become live cash)' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER money_import_guard BEFORE INSERT ON account_balances FOR EACH ROW EXECUTE FUNCTION guard_money_insert();
CREATE TRIGGER money_import_guard BEFORE INSERT ON journal_lines FOR EACH ROW EXECUTE FUNCTION guard_money_insert();

CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable table %',TG_TABLE_NAME USING ERRCODE='55000'; END $$;
CREATE FUNCTION guard_line_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM kita.journals WHERE id=NEW.journal_id AND creation_tx=txid_current()) THEN RAISE EXCEPTION 'cannot append to a committed journal'; END IF; RETURN NEW; END $$;
CREATE TRIGGER journal_line_insert_guard BEFORE INSERT ON journal_lines FOR EACH ROW EXECUTE FUNCTION guard_line_insert();
CREATE FUNCTION check_journal_balance() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE j uuid; BEGIN
 IF TG_TABLE_NAME='journals' THEN j:=NEW.id; ELSE j:=NEW.journal_id; END IF;
 IF (SELECT count(*) FROM kita.journal_lines WHERE journal_id=j)<2 THEN RAISE EXCEPTION 'journal requires at least two lines'; END IF;
 IF EXISTS(SELECT currency FROM kita.journal_lines WHERE journal_id=j GROUP BY currency HAVING sum(CASE side WHEN 'D' THEN amount_minor::numeric ELSE -amount_minor::numeric END)<>0) THEN RAISE EXCEPTION 'unbalanced journal per currency'; END IF;
 RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER balance_header AFTER INSERT ON journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_journal_balance();
CREATE CONSTRAINT TRIGGER balance_lines AFTER INSERT ON journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_journal_balance();
CREATE FUNCTION guard_approval() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a kita.approvals; BEGIN
 SELECT * INTO STRICT a FROM kita.approvals WHERE id=NEW.approval_id FOR UPDATE;
 IF a.requester_person_id=NEW.approver_person_id OR a.state<>'pending' OR a.expires_at<=clock_timestamp() OR a.payload_hash<>NEW.signed_hash THEN RAISE EXCEPTION 'invalid independent approval'; END IF; RETURN NEW; END $$;
CREATE TRIGGER independent_approval BEFORE INSERT ON approval_decisions FOR EACH ROW EXECUTE FUNCTION guard_approval();
CREATE FUNCTION guard_attempt_transition() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE er boolean; BEGIN
 IF ROW(NEW.book_id,NEW.transfer_id,NEW.operation_id,NEW.provider_account_id,NEW.leg,NEW.sequence,NEW.external_reference,NEW.request_hash,NEW.request_ref,NEW.amount_minor,NEW.currency) IS DISTINCT FROM ROW(OLD.book_id,OLD.transfer_id,OLD.operation_id,OLD.provider_account_id,OLD.leg,OLD.sequence,OLD.external_reference,OLD.request_hash,OLD.request_ref,OLD.amount_minor,OLD.currency) THEN RAISE EXCEPTION 'attempt instruction is immutable'; END IF;
 IF NEW.state<>OLD.state THEN
 SELECT evidence_required INTO er FROM kita.attempt_edges WHERE leg=NEW.leg AND from_state=OLD.state AND to_state=NEW.state;
 IF NOT FOUND THEN RAISE EXCEPTION 'illegal attempt transition'; END IF;
 IF er AND (NEW.last_evidence_id IS NULL OR NEW.last_evidence_id IS NOT DISTINCT FROM OLD.last_evidence_id OR NOT EXISTS(SELECT 1 FROM kita.evidence WHERE id=NEW.last_evidence_id AND verified AND book_id=NEW.book_id)) THEN RAISE EXCEPTION 'new verified evidence required'; END IF;
 IF NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'attempt version must advance'; END IF;
 END IF; RETURN NEW; END $$;
CREATE TRIGGER attempt_transition BEFORE UPDATE ON provider_attempts FOR EACH ROW EXECUTE FUNCTION guard_attempt_transition();

CREATE FUNCTION post_journal(p_book uuid,p_event text,p_policy uuid,p_evidence uuid,p_transfer uuid,p_reversal uuid,p_adjustment uuid,p_effective timestamptz,p_description text,p_lines jsonb) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,kita SET TimeZone='UTC' AS $$
DECLARE jid uuid; existing kita.journals; rh text; a record; del numeric; n integer:=0; item jsonb; oldbook uuid;
BEGIN
 -- Sole sanctioned path for balance/amount rows; unlocks the install-time money-import guards.
 PERFORM set_config('kita.posting_allowed','on',true);
 IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)<2 THEN RAISE EXCEPTION 'lines array required'; END IF;
 rh:=encode(digest(convert_to(jsonb_build_object('book',p_book,'event',p_event,'policy',p_policy,'evidence',p_evidence,'transfer',p_transfer,'reversal',p_reversal,'adjustment',p_adjustment,'effective',p_effective,'description',p_description,'lines',p_lines)::text,'UTF8'),'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(p_book::text||':'||p_event,0));
 SELECT * INTO existing FROM kita.journals WHERE book_id=p_book AND event_key=p_event;
 IF FOUND THEN IF existing.request_hash<>rh THEN RAISE EXCEPTION 'idempotency payload mismatch'; END IF; RETURN existing.id; END IF;
 IF NOT EXISTS(SELECT 1 FROM kita.accounting_periods WHERE book_id=p_book AND state='open' AND (clock_timestamp() AT TIME ZONE 'UTC')::date>=start_date AND (clock_timestamp() AT TIME ZONE 'UTC')::date<end_date) THEN RAISE EXCEPTION 'no open posting period'; END IF;
 IF NOT EXISTS(SELECT 1 FROM kita.evidence WHERE id=p_evidence AND book_id=p_book AND verified) THEN RAISE EXCEPTION 'verified evidence required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM kita.policies WHERE id=p_policy AND book_id=p_book AND kind='posting') THEN RAISE EXCEPTION 'posting policy required'; END IF;
 IF p_reversal IS NOT NULL THEN
 SELECT book_id INTO oldbook FROM kita.journals WHERE id=p_reversal;
 IF oldbook IS DISTINCT FROM p_book THEN RAISE EXCEPTION 'invalid reversal book'; END IF;
 END IF;
 IF p_adjustment IS NOT NULL AND NOT EXISTS(SELECT 1 FROM kita.journals WHERE id=p_adjustment AND book_id=p_book) THEN RAISE EXCEPTION 'invalid adjustment book'; END IF;
 -- Validate all referenced accounts and acquire locks in UUID order before reading balances.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_lines) x LEFT JOIN kita.ledger_accounts a ON a.id=(x->>'account_id')::uuid AND a.book_id=p_book AND a.currency=x->>'currency' WHERE a.id IS NULL) THEN RAISE EXCEPTION 'account/entity/currency mismatch'; END IF;
 FOR a IN SELECT la.* FROM kita.ledger_accounts la WHERE la.id IN (SELECT (x->>'account_id')::uuid FROM jsonb_array_elements(p_lines)x) ORDER BY la.id FOR UPDATE LOOP
 INSERT INTO kita.account_balances(account_id) VALUES(a.id) ON CONFLICT DO NOTHING;
 SELECT sum(CASE WHEN x->>'side'=a.normal_side THEN (x->>'amount_minor')::numeric ELSE -(x->>'amount_minor')::numeric END) INTO del FROM jsonb_array_elements(p_lines)x WHERE (x->>'account_id')::uuid=a.id;
 IF a.enforce_nonnegative AND (SELECT normal_minor+del FROM kita.account_balances WHERE account_id=a.id)<0 THEN RAISE EXCEPTION 'insufficient balance'; END IF;
 UPDATE kita.account_balances SET normal_minor=normal_minor+del,version=version+1 WHERE account_id=a.id;
 END LOOP;
 INSERT INTO kita.journals(book_id,event_key,request_hash,policy_id,evidence_id,transfer_id,reversal_of,adjustment_of,effective_at,description) VALUES(p_book,p_event,rh,p_policy,p_evidence,p_transfer,p_reversal,p_adjustment,p_effective,p_description) RETURNING id INTO jid;
 FOR item IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
 n:=n+1;
 INSERT INTO kita.journal_lines VALUES(jid,n,p_book,(item->>'account_id')::uuid,item->>'currency',item->>'side',(item->>'amount_minor')::bigint);
 END LOOP;
 IF EXISTS(SELECT currency FROM kita.journal_lines WHERE journal_id=jid GROUP BY currency HAVING sum(CASE side WHEN 'D' THEN amount_minor::numeric ELSE -amount_minor::numeric END)<>0) THEN RAISE EXCEPTION 'unbalanced journal'; END IF;
 IF p_reversal IS NOT NULL AND EXISTS(
 SELECT account_id,currency FROM kita.journal_lines WHERE journal_id IN(jid,p_reversal) GROUP BY account_id,currency HAVING sum(CASE side WHEN 'D' THEN amount_minor::numeric ELSE -amount_minor::numeric END)<>0) THEN RAISE EXCEPTION 'full reversal must exactly negate original accounts'; END IF;
 RETURN jid;
END $$;

DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['quotes','recipient_versions','consents','evidence','journals','journal_lines','ledger_accounts','transfer_events','approval_decisions','audit_events','identity_decisions','screenings','point_events','point_lots','statement_lines','refund_obligations','receipts','policies','mandates','mandate_revocations','rate_snapshots','wallet_quotes','fx_trades','fx_allocations','case_messages'] LOOP
 EXECUTE format('CREATE TRIGGER immutable_rows BEFORE UPDATE OR DELETE ON kita.%I FOR EACH ROW EXECUTE FUNCTION kita.reject_mutation()',t);
 END LOOP; END $$;

REVOKE ALL ON SCHEMA kita FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA kita FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA kita FROM PUBLIC;
GRANT USAGE ON SCHEMA kita TO kita_api,kita_worker,kita_posting,kita_auditor;
GRANT SELECT ON ALL TABLES IN SCHEMA kita TO kita_auditor;
GRANT EXECUTE ON FUNCTION post_journal(uuid,text,uuid,uuid,uuid,uuid,uuid,timestamptz,text,jsonb) TO kita_posting;
-- No generic table writes granted to runtime roles. Follow-on domain migrations expose
-- narrowly authorized command functions; no runtime UPDATE/DELETE/INSERT on journals,
-- journal_lines, ledger_accounts, account_balances, or approval_decisions.
-- Audit readers here are backend service identities; human data access remains scoped.
ALTER DEFAULT PRIVILEGES IN SCHEMA kita REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

COMMIT;
